{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 11,
      "text_ar": "وكان في الليلة الثانية أني رأيت حلما، وإذا بعقاب لها اثنا عشر جناحا مكسوا بالريش وثلاث رؤوس طلعت من البحر.",
      "verse": 1
    },
    {
      "chapter": 11,
      "text_ar": "ورأيت، وإذا بها بسطت أجنحتها على الأرض كلها، وهبت عليها كل رياح السماء، وتجمعت السحب ضدها.",
      "verse": 2
    },
    {
      "chapter": 11,
      "text_ar": "ورأيت، ومن أجنحتها نمت أجنحة أخرى بجانبها، وصارت أجنحة صغيرة دقيقة.",
      "verse": 3
    },
    {
      "chapter": 11,
      "text_ar": "أما رؤوسها فكانت استراحة. وكان الرأس الذي في الوسط أكبر من الرأسين الآخرين، ولكنه استراح معهما.",
      "verse": 4
    },
    {
      "chapter": 11,
      "text_ar": "وأيضا رأيت، وإذا بالعقاب طارت بأجنحتها لتمسح على الأرض وعلى الساكنين فيها.",
      "verse": 5
    }
  ]
}
